35	function useDecide() {
36	  const [pending, start] = useTransition();
37	  const [error, setError] = useState<string>();
38	  const run = (work: () => Promise<string | void>) => start(async () => {
39	    setError(undefined);
40	    try { const failed = await work(); if (failed) setError(failed); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not save"); }
41	  });
42	  return { pending, error, run };
43	}
