46	export function RecurringSheet({ proposals }: { proposals: OpenProposal[] }) {
47	  const { pending, error, run } = useDecide();
48	  const [version, setVersion] = useState(0);
49	  return <div>
50	    <div className="mt-2 flex flex-wrap items-center gap-2"><p className="mr-auto text-sm text-muted-foreground">Confirmed payments go into your forecast. “Not recurring” is remembered.</p>
51	      <button type="button" disabled={pending} className={primary} onClick={() => run(async () => {
52	        const outcomes = await decideAgentProposals(proposals.map(item => item.id), "accept");
53	        setVersion(count => count + 1);
54	        const failed = outcomes.filter(item => item.error);
55	        return failed.length ? `${failed.length} could not be saved: ${failed[0].error}` : undefined;
56	      })}>Confirm all</button></div>
57	    {error && <p role="alert" className="mt-2 text-sm text-danger">{error}</p>}
58	    {/* Remounting after Confirm all reloads every card's outcome. */}
59	    {proposals.map(proposal => <IouCard key={`${proposal.id}:${version}`} id={proposal.id} initial={version ? undefined : proposal} />)}
60	  </div>;
