86	/** Uncategorized spending grouped by description: pick a category per group (the suggestion is preselected) or skip it. */
87	export function UncategorizedSheet({ total }: { total: number }) {
88	  const [data, setData] = useState<Awaited<ReturnType<typeof loadUncategorizedGroups>>>();
89	  const [chosen, setChosen] = useState<Record<string, string>>({});
90	  const [done, setDone] = useState<Record<string, string>>({});
91	  const { pending, error, run } = useDecide();
92	  useEffect(() => { loadUncategorizedGroups().then(setData, () => setData({ groups: [], total: 0, categories: [] })); }, []);
93	  if (!data) return <p role="status" className="mt-3 text-sm text-muted-foreground">Grouping {total} transactions…</p>;
94	  const pick = (group: UncategorizedGroup) => chosen[group.key] ?? group.suggested ?? "";
95	  const apply = (groups: UncategorizedGroup[]) => run(async () => {
96	    for (const group of groups) {
97	      const { applied } = await categorizeGroup({ rows: group.rows, categoryId: pick(group), key: group.key });
98	      setDone(current => ({ ...current, [group.key]: `${applied} categorized` }));
99	    }
100	  });
101	  const open = data.groups.filter(group => !done[group.key]);
102	  const suggested = open.filter(group => group.suggested && pick(group) === group.suggested);
103	  return <div>
104	    <div className="mt-2 flex flex-wrap items-center gap-2"><p className="mr-auto text-sm text-muted-foreground">Each choice also teaches a rule, so the next sync sorts these by itself. Every batch can be undone.</p>
105	      {suggested.length > 0 && <button type="button" disabled={pending} className={primary} onClick={() => apply(suggested)}>Apply {suggested.length} suggested</button>}</div>
106	    {error && <p role="alert" className="mt-2 text-sm text-danger">{error}</p>}
107	    <ul className="mt-2 divide-y divide-border">{data.groups.map(group => <li key={group.key} className="flex flex-wrap items-center gap-2 py-3">
108	      <div className="min-w-0 flex-1"><p className="truncate text-sm font-medium">{group.label}</p><p className="text-xs text-muted-foreground">{group.count} {group.count === 1 ? "transaction" : "transactions"}{group.suggested ? " · suggestion preselected" : ""}</p></div>
109	      {done[group.key] ? <p role="status" className="text-sm">{done[group.key]}</p> : <>
110	        <select aria-label={`Category for ${group.label}`} value={pick(group)} disabled={pending} onChange={event => setChosen(current => ({ ...current, [group.key]: event.target.value }))}
111	          className="min-h-9 max-w-44 rounded-lg border border-border bg-background px-2 text-sm">
112	          <option value="">Choose…</option>
113	          {data.categories.map(category => <option key={category.id} value={category.id}>{category.name}</option>)}
114	        </select>
115	        <button type="button" disabled={pending || !pick(group)} className={primary} onClick={() => apply([group])}>Apply</button>
116	        <button type="button" disabled={pending} className={secondary} onClick={() => setDone(current => ({ ...current, [group.key]: "Skipped" }))}>Skip</button>
117	      </>}
118	    </li>)}</ul>
119	    {data.total > data.groups.reduce((sum, group) => sum + group.count, 0) && <p className="mt-3 text-xs text-muted-foreground">Showing the {data.groups.length} biggest groups. <Link href="/money/organization" className="underline">Sort the rest on Organize</Link></p>}
120	  </div>;
121	}
