3	import { revalidatePath } from "next/cache";
4	import { z } from "zod";
5	import { requireWorkspace } from "@/lib/auth";
6	import { loadOrganizationSuggestions } from "@/lib/import/organization-loader";
7	import { organizationDescriptionKey } from "@/lib/import/organization";
8	
9	export type UncategorizedGroup = { key: string; label: string; count: number; rows: { id: string; version: number }[]; suggested: string | null };
10	
11	const MAX_GROUPS = 30;
12	
13	/** Uncategorized spending grouped by what the bank wrote, biggest groups first, each with the category the app would pick. */
14	export async function loadUncategorizedGroups() {
15	  const { supabase, workspace } = await requireWorkspace();
16	  const [rows, categories, proposals] = await Promise.all([
17	    supabase.from("transactions").select("id, version, description").eq("workspace_id", workspace.id).eq("status", "posted").is("category_id", null).neq("kind", "transfer")
18	      .order("posted_on", { ascending: false }).limit(1000),
19	    supabase.from("categories").select("id, name").eq("workspace_id", workspace.id).order("name").limit(500),
20	    // The Categorizer's picks it was not sure enough to apply.
21	    supabase.from("agent_proposals").select("payload").eq("workspace_id", workspace.id).eq("kind", "categorize").in("status", ["proposed", "failed"]).limit(200),
22	  ]);
23	  if (rows.error || categories.error || proposals.error) throw new Error((rows.error ?? categories.error ?? proposals.error)!.message);
24	  const picked = new Map<string, string>();
25	  for (const { payload } of proposals.data ?? []) {
26	    const category = payload?.patch?.category_id;
27	    if (typeof category === "string") for (const row of payload.rows ?? []) picked.set(row.id, category);
28	  }
29	  const groups = new Map<string, UncategorizedGroup>();
30	  for (const row of rows.data ?? []) {
31	    const key = organizationDescriptionKey(row.description) || row.description;
32	    const group: UncategorizedGroup = groups.get(key) ?? { key, label: row.description, count: 0, rows: [], suggested: null };
33	    group.count++;
34	    group.rows.push({ id: row.id, version: row.version });
35	    group.suggested ??= picked.get(row.id) ?? null;
36	    groups.set(key, group);
37	  }
38	  const top = [...groups.values()].sort((a, b) => b.count - a.count).slice(0, MAX_GROUPS);
39	  // History and approved rules suggest a category for groups the Categorizer left open.
40	  const open = top.filter(group => !group.suggested);
41	  if (open.length) {
42	    const history = await loadOrganizationSuggestions(supabase, workspace.id, open.map(group => group.rows[0])).catch(() => null);
43	    for (const proposal of history?.proposals ?? []) {
44	      const group = open.find(item => item.rows[0].id === proposal.transactionId);
45	      if (group && proposal.categoryId) group.suggested = proposal.categoryId;
46	    }
47	  }
48	  return { groups: top, total: rows.data?.length ?? 0, categories: (categories.data ?? []) as { id: string; name: string }[] };
49	}
50	
51	const groupInput = z.object({ rows: z.array(z.object({ id: z.uuid(), version: z.number().int().min(0) }).strict()).min(1).max(1000), categoryId: z.uuid(), key: z.string().max(1000) });
52	
53	/**
54	 * Categorizes a group through the audited organization review, 50 rows per batch, and saves a rule so later syncs
55	 * categorize the same description by themselves. Rows a person corrected meanwhile are left alone; each batch can be undone.
56	 */
57	export async function categorizeGroup(input: z.input<typeof groupInput>) {
58	  const { rows, categoryId, key } = groupInput.parse(input);
59	  const { supabase, workspace } = await requireWorkspace();
60	  let applied = 0;
61	  for (let offset = 0; offset < rows.length; offset += 50) {
62	    const current = await loadOrganizationSuggestions(supabase, workspace.id, rows.slice(offset, offset + 50));
63	    if (!current.proposals.length) continue;
64	    const evidence = [...new Map(current.proposals.flatMap(item => item.evidence).map(row => [row.id, row])).values()];
65	    const rule = offset === 0 && key.length >= 3 && current.proposals.every(item => item.descriptionKey === key) ? key : null;
66	    const created = await supabase.rpc("create_organization_review", { p_rows: current.proposals.map(item => ({ id: item.transactionId, version: item.version })),
67	      p_patch: { category_id: categoryId }, p_merchant_name: null, p_rule_key: rule, p_evidence: evidence, p_request_id: crypto.randomUUID() });
68	    if (created.error) throw new Error(created.error.message);
69	    const done = await supabase.rpc("apply_organization_review", { p_review_id: created.data.id, p_save_rule: rule !== null });
70	    if (done.error) throw new Error(done.error.message);
71	    applied += current.proposals.length;
72	  }
73	  revalidatePath("/", "layout");
74	  return { applied };
75	}
