10	const FILTERS = [["loans", "Loans"], ["transactions", "Transactions"], ["balances", "Balances"]] as const;
11	type Filter = (typeof FILTERS)[number][0];
12	const filterOf = (kind: string): Filter => kind.startsWith("iou_") ? "loans" : kind === "transaction_create" ? "transactions" : "balances";
