15	/**
16	 * What waits for a decision: loans, expenses and balances as single cards; recurring, uncategorized and flagged items as one
17	 * summary card each that opens them in a sheet. Filtered-out cards stay mounted (hidden), so a card decided here keeps its outcome.
18	 */
19	export function WaitingForYouList({ proposals: all, review = { uncategorized: 0, findings: [] } }: { proposals: OpenProposal[]; review?: HomeReview }) {
20	  const [filter, setFilter] = useState<Filter>();
21	  const recurring = all.filter(proposal => proposal.kind === "recurring_edit");
22	  const proposals = all.filter(proposal => proposal.kind !== "recurring_edit");
23	  const count = all.length + review.findings.length + review.uncategorized;
24	  const present = FILTERS.filter(([key]) => proposals.some(proposal => filterOf(proposal.kind) === key));
25	  const chip = (active: boolean) => `h-9 rounded-full border px-3.5 text-[13px] transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ai ${active ? "border-foreground bg-foreground text-background" : "border-input text-muted-foreground hover:bg-muted hover:text-foreground"}`;
26	  return <details open aria-label="Waiting for you" className="group">
27	    <summary className="-mx-1 flex min-h-11 cursor-pointer list-none items-center gap-2.5 rounded-lg px-1 focus-visible:outline-2 focus-visible:outline-ai [&::-webkit-details-marker]:hidden">
28	      <span className="font-display text-lg font-semibold">Waiting for you</span>
29	      <span className="rounded-full bg-ai-soft px-2 py-0.5 text-xs font-medium text-ai tabular-nums">{count}</span>
30	      <ChevronDown className="ml-auto size-4 text-muted-foreground transition-transform group-not-open:-rotate-90" aria-hidden="true" />
31	    </summary>
