     5	
     6	type FindingRow = { id: string; conflict_key: string; title: string; detail: string; evidence: { links?: { href: string }[]; transactions?: { id: string }[] } | null };
     7	
     8	/** What the after-sync checks left for a person: uncategorized spending and open findings, one entry per finding however many runs raised it. */
     9	export async function loadHomeReview(supabase: SupabaseClient, workspaceId: string): Promise<HomeReview> {
    10	  const [uncategorized, findings] = await Promise.all([
    11	    // Transfers between accounts need no category.
    12	    supabase.from("transactions").select("id", { count: "exact", head: true }).eq("workspace_id", workspaceId).eq("status", "posted").is("category_id", null).neq("kind", "transfer"),
    13	    supabase.from("agent_proposals").select("id, conflict_key, title, detail, evidence").eq("workspace_id", workspaceId).eq("kind", "finding").eq("status", "proposed")
    14	      .not("run_id", "is", null).order("created_at", { ascending: false }).limit(300),
    15	  ]);
    16	  if (uncategorized.error) throw new Error(uncategorized.error.message);
    17	  if (findings.error) throw new Error(findings.error.message);
    18	  const byKey = new Map<string, HomeFinding>();
    19	  for (const row of (findings.data ?? []) as FindingRow[]) {
    20	    const known = byKey.get(row.conflict_key);
    21	    if (known) { known.ids.push(row.id); continue; }
    22	    const transaction = row.evidence?.transactions?.[0]?.id;
    23	    byKey.set(row.conflict_key, { ids: [row.id], title: row.title, detail: row.detail,
    24	      href: transaction ? `/money/transactions?transaction=${transaction}` : row.evidence?.links?.[0]?.href ?? null });
    25	  }
    26	  return { uncategorized: uncategorized.count ?? 0, findings: [...byKey.values()] };
    27	}
