 5	/** The change between a series' two latest posted charges in the same currency (positive = price went up), or null. */
 6	export function latestPriceChange(charges: Charge[]) {
 7	  const [latest, previous] = [...charges].sort((a, b) => b.postedOn.localeCompare(a.postedOn));
 8	  if (!latest || !previous || latest.currencyCode !== previous.currencyCode) return null;
 9	  const abs = (value: bigint) => value < 0n ? -value : value;
10	  const changeMinor = abs(latest.amountMinor) - abs(previous.amountMinor);
11	  return changeMinor === 0n ? null : { changeMinor, currencyCode: latest.currencyCode, since: latest.postedOn };
12	}
