import io
def edit(p, pairs):
    s=io.open(p,encoding='utf-8').read()
    for a,b in pairs:
        assert a in s, (p, a[:90])
        s=s.replace(a,b)
    io.open(p,'w',encoding='utf-8',newline='\n').write(s)

